import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, vec3, smoothstep, float, texture, clamp, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight, Box3, Vector3 } = THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const C_BG = colors.background ?? '#0b0b10';
  const C_SURF = colors.surface ?? '#14141a';
  const C_INK = colors.ink ?? '#16161d';
  const C_PAPER = colors.paper ?? '#e8ecf2';
  const C_ACCENT = colors.accent ?? '#ff2a38';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItems = items.filter((i) => i.role === 'caption');
  const headlineText = headlineItem ? headlineItem.text : 'Inside the atelier';
  const captionTexts = captionItems.length
    ? captionItems.map((i) => i.text)
    : ['DIAL ROOM', 'ESCAPEMENT BENCH', 'CNC HALL', 'FINISHING LAB', 'ARCHIVE VAULT', 'ASSEMBLY LINE ONE'];

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primResults = [];
  let loadedTex = null;

  // ---------- helper: normalize fontAtlas output to exact scene-unit sizes ----------
  // Guards against atlas-unit mismatch (the prior render's giant blown-white glyph slabs).
  function placeText(obj, x, y, z, targetH, maxW) {
    const box = new Box3().setFromObject(obj);
    const size = new Vector3();
    box.getSize(size);
    let s = 1;
    if (size.y > 1e-6) s = targetH / size.y;
    if (maxW && size.x > 1e-6 && size.x * s > maxW) s = maxW / size.x;
    obj.scale.multiplyScalar(s);
    const box2 = new Box3().setFromObject(obj);
    obj.position.x += x - box2.min.x;
    obj.position.y += y - (box2.min.y + box2.max.y) / 2;
    obj.position.z = z;
  }

  // shared subtle film grain node
  function grainNode(scale, amp) {
    const n = fract(sin(dot(uv().mul(vec2(scale, scale * 2.417)), vec2(12.9898, 78.233))).mul(43758.5453));
    return n.sub(float(0.5)).mul(float(amp));
  }

  // ---------- BACKDROP — full-frame engineered gradient stage (no flat void anywhere) ----------
  const backdropGeo = new PlaneGeometry(16, 12);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const u = uv();
    const grad = mix(color(C_BG), color(C_SURF), smoothstep(float(0.0), float(1.0), u.y));
    // lift the left third — headline + index field never sits on raw black
    const leftLift = smoothstep(float(0.58), float(0.0), u.sub(vec2(0.28, 0.6)).length());
    // warm halo behind the plate column so ink frames separate from the stage
    const colHalo = smoothstep(float(0.5), float(0.0), u.sub(vec2(0.556, 0.5)).length());
    // faint accent wash bleeding off the focused plate's lit edge (well under 10% accent)
    const accentWash = smoothstep(float(0.16), float(0.0), u.sub(vec2(0.5, 0.5)).length()).mul(0.06);
    backdropMat.colorNode = grad
      .add(color('#26242a').mul(leftLift.mul(0.85)))
      .add(color('#2c2823').mul(colHalo.mul(0.7)))
      .add(color(C_ACCENT).mul(accentWash))
      .add(vec3(1, 1, 1).mul(grainNode(240.0, 0.03)));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.6);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- LOCAL LIGHTS — accent rim from the left, low neutral fill ----------
  const rim = new PointLight(C_ACCENT, 1.1, 9);
  rim.position.set(-1.7, 0.3, 1.5);
  group.add(rim);
  const fill = new PointLight('#cdd3dc', 0.35, 12);
  fill.position.set(3.0, 2.2, 3.0);
  group.add(fill);

  // ---------- LEFT STRUCTURE — machined vertical rail behind the index (fills left field) ----------
  const railBarGeo = new BoxGeometry(0.025, 4.2, 0.025);
  const railBarMat = new MeshStandardNodeMaterial({ color: '#3a3a44', roughness: 0.5, metalness: 0.5 });
  const railBar = new Mesh(railBarGeo, railBarMat);
  railBar.position.set(-2.95, 0.2, 0.05);
  group.add(railBar);
  disposables.push(railBarGeo, railBarMat);

  // ---------- HEADLINE — pinned at [-1.6, 1.9], normalized to display scale ----------
  const headlineObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineItem?.typography?.fontSize ?? 68,
    color: C_PAPER,
    align: 'left',
  });
  group.add(headlineObj);
  placeText(headlineObj, -1.6, 1.9, 0.55, 0.3, 2.3);

  const ruleGeo = new PlaneGeometry(0.55, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({
    color: C_ACCENT, emissive: C_ACCENT, emissiveIntensity: 1.0,
    roughness: 0.6, metalness: 0.1,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.325, 1.62, 0.55);
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------- INDEX RAIL — caption copy verbatim, caption scale ----------
  const railYs = [];
  const railTexts = [];
  for (let i = 0; i < captionTexts.length; i++) {
    const y = 1.05 - i * 0.32;
    railYs.push(y);
    const t = ctx.fontAtlas.createText(captionTexts[i], {
      fontSize: 18, color: C_PAPER, align: 'left', letterSpacingPx: 1.5,
    });
    group.add(t);
    placeText(t, -2.8, y, 0.1, 0.075, 1.1);
    t.traverse((o) => { if (o.material) { o.material.transparent = true; o.material.opacity = 0.5; } });
    railTexts.push(t);
  }
  const markerGeo = new PlaneGeometry(0.05, 0.05);
  const markerMat = new MeshStandardNodeMaterial({
    color: C_ACCENT, emissive: C_ACCENT, emissiveIntensity: 1.2,
    roughness: 0.6, metalness: 0.1,
  });
  const marker = new Mesh(markerGeo, markerMat);
  marker.position.set(-2.95, railYs[0], 0.1);
  group.add(marker);
  disposables.push(markerGeo, markerMat);

  // ---------- LOOP COLUMN — 6 plates, 1.9 x 1.2, pitch 1.5, x = +0.9, modulo 9 ----------
  const COUNT = 6;
  const PITCH = 1.5;
  const LOOP = COUNT * PITCH;

  const flyRig = new Group();
  group.add(flyRig);
  const columnRig = new Group();
  columnRig.position.set(0.9, 0, 0);
  flyRig.add(columnRig);

  const plateGeo = new PlaneGeometry(1.9, 1.2);
  const frameGeo = new BoxGeometry(1.96, 1.26, 0.06);
  const stripGeo = new PlaneGeometry(0.03, 1.2);
  disposables.push(plateGeo, frameGeo, stripGeo);

  // per-plate distinct crop + filmic grade (warm-neutral, mid-toned, never void)
  const crops = [
    { r: 1.0,  x: 0.0,  y: 0.0,  tr: 1.0,  tg: 0.97, tb: 0.93, hx: 0.35, hy: 0.6,  gx: 0.7, gy: 0.3 },
    { r: 0.8,  x: 0.1,  y: 0.15, tr: 0.95, tg: 0.95, tb: 0.97, hx: 0.62, hy: 0.42, gx: 0.3, gy: 0.7 },
    { r: 0.72, x: 0.25, y: 0.05, tr: 1.0,  tg: 0.95, tb: 0.88, hx: 0.5,  hy: 0.66, gx: 0.5, gy: 0.5 },
    { r: 0.68, x: 0.02, y: 0.28, tr: 0.93, tg: 0.94, tb: 0.94, hx: 0.3,  hy: 0.36, gx: 0.8, gy: 0.2 },
    { r: 0.65, x: 0.3,  y: 0.3,  tr: 1.0,  tg: 0.96, tb: 0.9,  hx: 0.66, hy: 0.56, gx: 0.4, gy: 0.6 },
    { r: 0.85, x: 0.12, y: 0.02, tr: 0.96, tg: 0.94, tb: 0.9,  hx: 0.44, hy: 0.46, gx: 0.6, gy: 0.4 },
  ];

  // pre-load placeholder — graded mid-tone still-life gradient, reads photographic
  function placeholderNode(i) {
    const c = crops[i];
    const u = uv();
    const diag = smoothstep(float(0.0), float(1.0), u.x.mul(float(c.gx)).add(u.y.mul(float(c.gy))));
    const base = mix(color('#2a2823'), color('#5a544a'), diag);
    const hot = smoothstep(float(0.55), float(0.0), u.sub(vec2(c.hx, c.hy)).length());
    const vig = smoothstep(float(1.25), float(0.3), u.sub(vec2(0.5, 0.5)).length().mul(2.0));
    return base
      .add(color('#8a8072').mul(hot.mul(0.45)))
      .mul(mix(float(0.55), float(1.0), vig))
      .add(vec3(1, 1, 1).mul(grainNode(160.0 + i * 13.0, 0.05)));
  }

  // loaded photograph — distinct crop, filmic tint, lifted blacks, baked vignette,
  // exposure ceiling so plates NEVER read as blown white
  function texturedNode(tex, i) {
    const c = crops[i];
    const u = uv();
    const cu = clamp(
      u.mul(float(c.r)).add(vec2(Math.min(c.x, 1 - c.r), Math.min(c.y, 1 - c.r))),
      float(0.0), float(1.0)
    );
    const t = texture(tex, cu);
    const vig = smoothstep(float(1.3), float(0.3), u.sub(vec2(0.5, 0.5)).length().mul(2.0));
    const graded = t.rgb.mul(vec3(c.tr, c.tg, c.tb)).mul(mix(float(0.5), float(0.85), vig));
    return clamp(graded.add(color('#16141a').mul(0.12)), float(0.0), float(0.9))
      .add(vec3(1, 1, 1).mul(grainNode(150.0 + i * 17.0, 0.04)));
  }

  const plates = [];
  for (let i = 0; i < COUNT; i++) {
    const holder = new Group();

    // machined ink bevel frame — brushed, responds to the accent rim light
    const frameMat = new MeshStandardNodeMaterial({ color: C_INK, roughness: 0.5, metalness: 0.5 });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.028;
    holder.add(frame);
    disposables.push(frameMat);

    // plate face is UNLIT — the photograph carries its own baked grade,
    // so scene lights can never blow it to white
    const plateMat = new MeshBasicNodeMaterial();
    plateMat.colorNode = placeholderNode(i);
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0.006;
    holder.add(plate);
    disposables.push(plateMat);

    const stripMat = new MeshStandardNodeMaterial({
      color: C_ACCENT, emissive: C_ACCENT, emissiveIntensity: 1.4,
      roughness: 0.6, metalness: 0.1, transparent: true, opacity: 0,
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-0.955, 0, 0.02);
    holder.add(strip);
    disposables.push(stripMat);

    holder.position.y = i * PITCH > LOOP / 2 ? i * PITCH - LOOP : i * PITCH;
    columnRig.add(holder);
    plates.push({ holder, plateMat, stripMat });
  }

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTex = tex;
    for (let i = 0; i < COUNT; i++) {
      plates[i].plateMat.colorNode = texturedNode(tex, i);
      plates[i].plateMat.needsUpdate = true;
    }
  }).catch(() => {});

  // ---------- FOCUSED CAPTIONS — fade up at x = -1.6 ----------
  const captionGroups = [];
  for (let i = 0; i < COUNT; i++) {
    const cap = ctx.fontAtlas.createText(captionTexts[i % captionTexts.length], {
      fontSize: 18, color: C_PAPER, align: 'left', letterSpacingPx: 1.5,
    });
    group.add(cap);
    placeText(cap, -1.6, -0.05, 0.3, 0.09, 1.6);
    cap.visible = false;
    const mats = [];
    cap.traverse((o) => {
      if (o.material) { o.material.transparent = true; o.material.opacity = 0; mats.push(o.material); }
    });
    captionGroups.push({ obj: cap, mats, baseY: cap.position.y });
  }

  // ---------- SCROLL STATE — weighted inertia (damping 0.12) ----------
  let target = 0;
  let current = 0;
  let focused = -1;

  function wrapY(baseY) {
    return ((baseY + current + LOOP / 2) % LOOP + LOOP) % LOOP - LOOP / 2;
  }

  function setFocus(i) {
    if (i === focused) return;
    if (focused >= 0) {
      const old = plates[focused];
      gsap.to(old.holder.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' });
      gsap.to(old.stripMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
      const oc = captionGroups[focused];
      gsap.to(oc.mats, {
        opacity: 0, duration: 0.25, ease: 'power2.out',
        onComplete: () => { oc.obj.visible = false; },
      });
    }
    focused = i;
    if (i >= 0) {
      const nw = plates[i];
      gsap.to(nw.holder.scale, { x: 1.06, y: 1.06, z: 1.06, duration: 0.35, ease: 'power2.out' });
      gsap.to(nw.stripMat, { opacity: 1, duration: 0.35, ease: 'power2.out' });
      const nc = captionGroups[i];
      nc.obj.visible = true;
      nc.obj.position.y = nc.baseY - 0.18;
      gsap.to(nc.obj.position, { y: nc.baseY, duration: 0.5, ease: 'power2.out' });
      gsap.to(nc.mats, { opacity: 1, duration: 0.4, ease: 'power2.out' });
      gsap.to(marker.position, { y: railYs[i % railYs.length], duration: 0.4, ease: 'power3.out' });
    }
  }

  const ticker = (t, deltaMS) => {
    const dt = Math.min(deltaMS / 1000, 0.05);
    target += 0.06 * dt; // ONE slow idle transform: gentle column cycle
    current += (target - current) * 0.12;
    let best = -1;
    let bestDist = Infinity;
    for (let i = 0; i < COUNT; i++) {
      const y = wrapY(i * PITCH);
      plates[i].holder.position.y = y;
      const d = Math.abs(y);
      if (d < bestDist) { bestDist = d; best = i; }
    }
    setFocus(best);
  };
  gsap.ticker.add(ticker);
  ticker(0, 16); // lay out the column immediately — a plate sits focused at y=0 on frame one

  // ---------- ENTRANCE — rise-in + weighted-settle ----------
  const enter = gsap.timeline();
  columnRig.position.y = -0.4;
  enter.to(columnRig.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  enter.fromTo(columnRig.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, '-=0.25');
  timelines.push(enter);

  // ---------- CINEMATIC PRIMITIVES — fly-through scoped to the column rig only ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) primResults.push(fn(flyRig, p.params ?? {}));
  }

  // ---------- HANDLERS ----------
  group.userData.handlers = {
    scroll: (e) => {
      if (e && typeof e.progress === 'number') {
        target = e.progress * LOOP;
      } else {
        const d = (e && (e.deltaY ?? e.delta ?? 0)) || 0;
        target += d * 0.0015 * PITCH;
      }
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    gsap.ticker.remove(ticker);
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(columnRig.position);
    gsap.killTweensOf(columnRig.scale);
    gsap.killTweensOf(marker.position);
    for (const p of plates) {
      gsap.killTweensOf(p.holder.scale);
      gsap.killTweensOf(p.stripMat);
    }
    for (const c of captionGroups) {
      gsap.killTweensOf(c.obj.position);
      gsap.killTweensOf(c.mats);
    }
    for (const r of primResults) { if (r && r.cleanup) r.cleanup(); }
    for (const d of disposables) { if (d.dispose) d.dispose(); }
    if (loadedTex && loadedTex.dispose) loadedTex.dispose();
  };

  return group;
}
